def main(data: str) -> dict:
    import json

    chapters = (
        "活动概况与重点关注", "日进站量/出站量", "日最大断面量",
        "全日分时最大断面量", "日换乘量", "日OD量",
    )
    value = data
    # 平台声明为string；也兼容本地对象与inputs.data完整请求包装。
    for _ in range(8):
        if isinstance(value, str):
            if len(value) > 2000000:
                raise ValueError("输入超过2000000字符，请缩减后重试")
            text = value.strip()
            while text and ord(text[0]) == 0xFEFF:
                text = text[1:].strip()
            try:
                # 用tuple保留对象键值对，防止重复章节被json.loads静默覆盖。
                decoded = json.loads(text, object_pairs_hook=tuple)
            except (TypeError, ValueError):
                raise ValueError("data必须是合法JSON对象字符串")
            if isinstance(decoded, str):
                value = decoded
                continue
            if not isinstance(decoded, tuple):
                raise ValueError("data的JSON根节点必须是对象")
            value = {}
            pending = [(decoded, value)]
            while pending:
                pairs, target = pending.pop()
                for key, item in pairs:
                    if key in target:
                        raise ValueError("JSON存在重复字段：" + key)
                    if isinstance(item, tuple):
                        child = {}
                        target[key] = child
                        pending.append((item, child))
                    else:
                        target[key] = item
        if not isinstance(value, dict):
            raise ValueError("data必须是对象或JSON对象字符串")
        if any(chapter in value for chapter in chapters):
            break
        if isinstance(value.get("inputs"), dict) and "data" in value["inputs"]:
            value = value["inputs"]["data"]
        elif "data" in value:
            value = value["data"]
        else:
            break
    else:
        raise ValueError("data包装层数过多")

    # 业务对象根层直接是六章正文，平台调用包装已在上方解开。
    sections = value
    missing = [key for key in chapters if key not in sections]
    if missing:
        raise ValueError("缺少章节：" + "、".join(missing))
    extra = [str(key) for key in sections if key not in chapters]
    if extra:
        raise ValueError("未知章节：" + "、".join(extra))

    parts = ["# 沿线活动客流分析报告"]
    for chapter in chapters:
        body = sections[chapter]
        if not isinstance(body, str) or not body.strip():
            raise ValueError("章节正文必须是非空字符串：" + chapter)
        # 正文不裁剪、不润色、不重算；包括用户输入的空白和Markdown格式。
        parts.append("## " + chapter + "\n\n" + body)
    md_text = "\n\n".join(parts) + "\n"
    if len(md_text) > 2000000:
        raise ValueError("汇总正文超过2000000字符，请缩减后重试")
    return {"md_text": md_text, "format": "word"}

def main(is_error: float, content: list[dict], md_text: str) -> dict:
    import json
    import re
    from urllib.parse import urlsplit

    if not isinstance(is_error, (int, float)) or is_error != 0:
        raise ValueError("Word导出服务返回错误，请重试")
    if not isinstance(md_text, str) or not md_text.strip():
        raise ValueError("汇总正文为空")
    if not isinstance(content, list) or not content or any(not isinstance(item, dict) for item in content):
        raise ValueError("Word导出响应content必须是非空对象数组")

    candidates = []
    pending = [(item, None) for item in content]
    visited = 0
    while pending:
        value, inherited_status = pending.pop()
        visited += 1
        if visited > 10000:
            raise ValueError("Word导出响应结构过大")
        if isinstance(value, str):
            text = value.strip()
            while text and ord(text[0]) == 0xFEFF:
                text = text[1:].strip()
            if text.startswith("```"):
                lines = text.splitlines()
                if len(lines) >= 3 and lines[0].strip().lower() in ("```", "```json") and lines[-1].strip() == "```":
                    text = "\n".join(lines[1:-1])
            try:
                decoded = json.loads(text, object_pairs_hook=tuple)
            except (TypeError, ValueError):
                # 说明文字不作为链接来源，不从任意URL猜测下载地址。
                continue
            if not isinstance(decoded, tuple):
                continue
            value = {}
            objects = [(decoded, value)]
            while objects:
                pairs, target = objects.pop()
                for key, item in (pairs if isinstance(pairs, tuple) else enumerate(pairs)):
                    if isinstance(target, dict) and key in target:
                        raise ValueError("Word导出响应存在重复字段：" + key)
                    child = {} if isinstance(item, tuple) else [] if isinstance(item, list) else item
                    if isinstance(target, dict):
                        target[key] = child
                    else:
                        target.append(child)
                    if isinstance(item, (tuple, list)):
                        objects.append((item, child))
        if isinstance(value, list):
            pending.extend((item, inherited_status) for item in value)
            continue
        if not isinstance(value, dict):
            continue
        status = value.get("status", inherited_status)
        if "status" in value and value["status"] != "success":
            raise ValueError("Word导出业务状态不是success")
        if value.get("isError") or value.get("is_error") or value.get("success") is False:
            raise ValueError("Word导出服务返回业务错误")
        if "download_url" in value:
            if status != "success":
                raise ValueError("下载地址缺少同层或上层status=success")
            candidate = value["download_url"]
            if not isinstance(candidate, str) or not candidate.strip():
                raise ValueError("download_url必须是非空字符串")
            candidate = candidate.strip()
            link = re.fullmatch(r"\[[^\]\r\n]*\]\((https?://[^\s<>]+)\)", candidate, re.IGNORECASE)
            if link:
                candidate = link.group(1)
            try:
                parsed = urlsplit(candidate)
                port = parsed.port
                valid = parsed.scheme in ("http", "https") and bool(parsed.hostname)
            except ValueError:
                valid = False
            if not valid or any(ord(char) <= 32 or ord(char) == 127 or char in '<>"\\' for char in candidate):
                raise ValueError("download_url必须是有效的HTTP或HTTPS绝对地址")
            candidates.append(candidate)
        # 仅解释服务结构字段和MCP文本块，不遍历正文、备注或任意业务字段。
        for key in ("data", "result", "content"):
            if key in value:
                pending.append((value[key], status))
        if value.get("type") == "text" and isinstance(value.get("text"), str):
            pending.append((value["text"], status))

    urls = set(candidates)
    if len(urls) != 1:
        raise ValueError("Word导出未返回唯一有效下载地址")
    download_url = candidates[0]
    return {"download_url": download_url, "md_text": md_text}
